import fs from 'node:fs/promises';
import path from 'node:path';
import {createHash} from 'node:crypto';
import {pathToFileURL} from 'node:url';
import {RemoteD1Database} from '../runner/report2-d1-adapter.mjs';
import {loadDailyUsageAggregate,evaluateDailyReservationBudget,evaluateWithinRunReservation,reserveRunBudget,finalizeRunUsage} from '../runner/d1-preaction-budget-guard.mjs';
import {buildBinanceArchiveUrl} from '../architecture-cleanup-delta/canonical-final-overlay/src/binance-public-data-history.mjs';
const load=n=>import(pathToFileURL(path.resolve('runtime/src',n)));
const [{createUnifiedHttpBudget},{reserveEvidenceSourceAttempts}]=await Promise.all([load('unified-budget.mjs'),load('evidence-source-store.mjs')]);
const db=new RemoteD1Database(process.env.REPORT2_D1_BRIDGE_URL,process.env.REPORT2_D1_BRIDGE_TOKEN),now=Date.now(),id='BINANCE_MONTHLY_COLD:'+process.env.GITHUB_RUN_ID+':'+process.env.GITHUB_RUN_ATTEMPT,root='audit-output/binance-monthly',budget=createUnifiedHttpBudget(),reservation={rows_read:1000,rows_written:64},hash=b=>createHash('sha256').update(b).digest('hex');
const out={schema:'BINANCE_MONTHLY_ORIGINAL_BATCH_V1',head:process.env.GITHUB_SHA,cloud_run:Number(process.env.GITHUB_RUN_ID),run_id:id,started_ts:now,symbol:'BTCUSDT',months:['2026-06','2026-07','2026-08'],markets:['spot','usd_m_futures'],sourceHTTP:0,max_sourceHTTP:12,cold_only:true,new_production_source_enabled:false,archives:[],MAIN:0,Telegram:0,actual_ENTRY:false,project_complete:false,source_clocks_refreshed:false};
await fs.mkdir(root,{recursive:true});let reserved=false;
async function original(url,file,max,record){
 if(out.sourceHTTP>=12||!evaluateWithinRunReservation({reservation,currentUsage:db.usageSnapshot(),extraRowsRead:10,extraRowsWritten:2}).allowed)throw Error('PREACTION_ENVELOPE_REQUIRED');
 const g=budget.reserve({logical_request_id:id+':'+url,lane:'statistics',attempts:1});if(!g.allowed||g.duplicate)throw Error('HTTP_ADMISSION_REQUIRED');
 out.sourceHTTP++;const receipt={url,started_ts:Date.now(),file};record.receipts.push(receipt);
 try{const r=await fetch(url,{redirect:'manual',signal:AbortSignal.timeout(20000)});receipt.http_status=r.status;const chunks=[];let total=0;for await(const chunk of r.body){total+=chunk.length;if(total>max){await r.body?.cancel?.().catch(()=>{});throw Error('BOUNDED_DOWNLOAD_REQUIRED');}chunks.push(chunk);}const b=Buffer.concat(chunks);Object.assign(receipt,{received_ts:Date.now(),bytes:b.length,sha256:hash(b),server_date:r.headers.get('date'),source_publication_clock_proven:false});await fs.writeFile(root+'/'+record.market+'/'+record.month+'/'+file,b);if(r.status!==200)throw Error('ARCHIVE_HTTP_'+r.status);return b;}catch(e){receipt.received_ts??=Date.now();receipt.failure_code=/^(?:ARCHIVE_HTTP_\d{3}|BOUNDED_DOWNLOAD_REQUIRED)$/.test(e.message)?e.message:['TimeoutError','AbortError','TypeError'].includes(e.name)?e.name:'TRANSPORT_NOT_CLOSED';throw Error(receipt.failure_code);}
}
try{
 out.day_admission=evaluateDailyReservationBudget({daily:await loadDailyUsageAggregate(db,now),nextReservation:reservation,maxDailyReads:3500000,maxDailyWrites:70000});if(!out.day_admission.allowed)throw Error('D1_DAILY_ADMISSION_BLOCKED');await reserveRunBudget(db,{reservationId:id,now,reservation});reserved=true;
 out.source_admission=await reserveEvidenceSourceAttempts(db,{source:'BINANCE_DELAYED_MONTHLY_ARCHIVE_QUALIFICATION',reservation_id:id,attempts:12,daily_cap:12,now});if(!out.source_admission.allowed)throw Error('SINGLE_DAILY_COLD_BATCH_ALREADY_RESERVED');
 for(const market of out.markets)for(const month of out.months){const p=buildBinanceArchiveUrl({market,frequency:'monthly',data_type:'klines',symbol:out.symbol,interval:'1m',date:month+'-01T00:00:00Z'});if(p.status!=='CLOSED')throw Error('EXACT_ARCHIVE_PLAN_REQUIRED');const record={market,symbol:out.symbol,month,url:p.url,receipts:[]};out.archives.push(record);await fs.mkdir(root+'/'+market+'/'+month,{recursive:true});try{const checksum=await original(p.checksum_url,'original.zip.CHECKSUM',4096,record),fields=checksum.toString().trim().split(/\s+/);if(fields.length!==2||!/^[a-f0-9]{64}$/.test(fields[0])||fields[1].replace(/^\*/,'')!==path.basename(p.url))throw Error('OFFICIAL_CHECKSUM_FORMAT_NOT_CLOSED');const zip=await original(p.url,'original.zip',8*1024*1024,record);if(hash(zip)!==fields[0])throw Error('OFFICIAL_CHECKSUM_MISMATCH');record.status='ORIGINAL_ARCHIVE_RETAINED';}catch(e){record.status='ORIGINAL_ARCHIVE_NOT_CLOSED';record.reason=String(e.message).slice(0,150);}}
 out.status=out.archives.length===6&&out.archives.every(x=>x.status==='ORIGINAL_ARCHIVE_RETAINED')?'SIX_ORIGINAL_ARCHIVES_RETAINED':'ORIGINAL_BATCH_PARTIAL';
}catch(e){out.status='ORIGINAL_BATCH_NOT_CLOSED';out.reason=String(e.message).slice(0,150);}finally{
 out.http_budget=budget.summary();if(reserved)out.finalized_usage=await finalizeRunUsage(db,{reservationId:id,sourceRunId:process.env.GITHUB_RUN_ID,usage:db.usageSnapshot()});out.D1=db.usageSnapshot();out.completed_ts=Date.now();if(out.D1.unknown_ops||out.D1.rows_read>reservation.rows_read||out.D1.rows_written>reservation.rows_written)out.status='D1_ENVELOPE_NOT_CLOSED';await fs.writeFile(root+'/acquisition.json',JSON.stringify(out,null,2)+'\n');console.log(JSON.stringify({status:out.status,sourceHTTP:out.sourceHTTP,D1:out.D1,archives:out.archives.map(x=>({market:x.market,month:x.month,status:x.status,reason:x.reason})),project_complete:false}));
}
